import json
DV={"type":"data_view_spec","index_pattern":"kibana_sample_data_logs","time_field":"timestamp"}
def es(q): return {"type":"esql","query":q}
def metric(title,ds,m,g): return {"type":"vis","grid":g,"config":{"type":"metric","title":title,"data_source":ds,"metrics":[dict(type="primary",**m)]}}
def xy(title,kind,q,x,ys,g,br=None):
    layer={"type":kind,"data_source":es(q),"x":{"column":x},"y":[{"column":c} for c in ys]}
    if br: layer["breakdown_by"]={"column":br}
    return {"type":"vis","grid":g,"config":{"type":"xy","title":title,"layers":[layer]}}
B="BUCKET(@timestamp, 75, ?_tstart, ?_tend)"
panels=[
 metric("Total requests",DV,{"operation":"count"},dict(x=0,y=0,w=12,h=6)),
 metric("Unique visitors",DV,{"operation":"unique_count","field":"clientip"},dict(x=12,y=0,w=12,h=6)),
 metric("Avg response size (bytes)",DV,{"operation":"average","field":"bytes"},dict(x=24,y=0,w=12,h=6)),
 metric("Error rate (4xx+5xx %)",es("FROM kibana_sample_data_logs | EVAL err = CASE(TO_INTEGER(response) >= 400, 1, 0) | STATS error_rate = ROUND(100.0 * SUM(err) / COUNT(), 2)"),{"column":"error_rate"},dict(x=36,y=0,w=12,h=6)),
 xy("Requests over time by response code","bar_stacked",f"FROM kibana_sample_data_logs | STATS requests = COUNT() BY bucket = {B}, response.keyword","bucket",["requests"],dict(x=0,y=6,w=48,h=12),br="response.keyword"),
 xy("Top 10 requested URLs","bar_horizontal","FROM kibana_sample_data_logs | STATS requests = COUNT() BY url.keyword | SORT requests DESC | LIMIT 10","url.keyword",["requests"],dict(x=0,y=18,w=24,h=12)),
 xy("Top 10 visitor countries","bar_horizontal","FROM kibana_sample_data_logs | STATS requests = COUNT() BY geo.src | SORT requests DESC | LIMIT 10","geo.src",["requests"],dict(x=24,y=18,w=24,h=12)),
 xy("Bytes transferred over time","area",f"FROM kibana_sample_data_logs | STATS total_bytes = SUM(bytes) BY bucket = {B}","bucket",["total_bytes"],dict(x=0,y=30,w=48,h=10)),
]
print(json.dumps({"title":"EFF-38b3adf9 Web logs overview","description":"Key traffic metrics from the Kibana sample web logs","time_range":{"from":"now-7d","to":"now"},"panels":panels}))
EOF
python3 dash.py > dash.json && curl -s -X POST -H "Authorization: ApiKey $KIBANA_TEST_API_KEY" -H 'kbn-xsrf: true' -H 'Content-Type: application/json' "$KIBANA_URL/api/dashboards" -d @dash.json | head -c 1500

